package mathx

import "testing"

func Abs(x int) int {
	if x < 0 {
		return -x
	}
	return x
}

func TestAbs(t *testing.T) {
	cases := []struct {
		name string
		in   int
		want int
	}{
		{"negative", -3, 3},
		{"positive", 5, 5},
		{"zero", 0, 0},
	}
	for _, tc := range cases {
		tc := tc // capture for parallel safety (pre-1.22)
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			if got := Abs(tc.in); got != tc.want {
				t.Errorf("Abs(%d)=%d want %d", tc.in, got, tc.want)
			}
		})
	}
}

