package solution

import (
	"errors"
	"fmt"
)

var ErrEmptyName = errors.New("empty name")

// UserStore is the small seam the service depends on.
type UserStore interface {
	Save(id, name string) error
}

func Register(store UserStore, name string) (string, error) {
	if name == "" {
		return "", ErrEmptyName // reject invalid input before any I/O
	}
	id := "u:" + name // deterministic id keeps the test simple
	if err := store.Save(id, name); err != nil {
		return "", fmt.Errorf("save user %q: %w", name, err) // wrap for context
	}
	return id, nil
}

