func TestFetch(t *testing.T) {
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		fmt.Fprint(w, "pong")
	}))
	defer srv.Close() // always tear the server down

	got, err := Fetch(srv.URL) // Fetch now uses a client with a Timeout set
	if err != nil {
		t.Fatalf("Fetch: %v", err)
	}
	if got != "pong" {
		t.Errorf("got %q, want pong", got)
	}
}

func TestParseRange(t *testing.T) {
	cases := []struct {
		name           string
		in             string
		wantLo, wantHi int
		wantErr        bool
	}{
		{"valid", "3-7", 3, 7, false},
		{"reversed", "7-3", 0, 0, true},
		{"not a number", "a-b", 0, 0, true},
		{"missing high", "1-", 0, 0, true},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			lo, hi, err := ParseRange(tc.in)
			if tc.wantErr {
				if err == nil {
					t.Fatalf("ParseRange(%q) expected error", tc.in)
				}
				return // don't check lo/hi on the error path
			}
			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if lo != tc.wantLo || hi != tc.wantHi {
				t.Errorf("ParseRange(%q)=%d,%d want %d,%d", tc.in, lo, hi, tc.wantLo, tc.wantHi)
			}
		})
	}
}
